CREATE OR REPLACE FUNCTION public.crm_quadro() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c uuid:=get_user_company_id(auth.uid());
BEGIN
 IF NOT crm_pode_ver(c) THEN RAISE EXCEPTION 'Sem acesso ao CRM'; END IF;
 RETURN jsonb_build_object('leads',coalesce((SELECT jsonb_agg(jsonb_build_object('id',l.id,'contato_id',l.contato_id,'paciente_id',l.paciente_id,'nome',l.nome,'interesse',l.interesse,'origem',l.origem,'etapa_id',l.etapa_id,'temperatura',l.temperatura,'temperatura_origem',l.temperatura_origem,'temperatura_regra',l.temperatura_regra,'temperatura_travada_ate',l.temperatura_travada_ate,'responsavel_id',l.responsavel_id,'responsavel_nome',inovachat_nome_usuario(l.responsavel_id),'valor_estimado',l.valor_estimado,'proximo_contato_em',l.proximo_contato_em,'motivo_perda_id',l.motivo_perda_id,'motivo_perda_texto',l.motivo_perda_texto,'criado_em',l.criado_em,'etapa_atualizada_em',l.etapa_atualizada_em,'fechado_em',l.fechado_em,'telefone',ct.telefone,'tags',coalesce((SELECT jsonb_agg(tag_id) FROM crm_lead_tags WHERE lead_id=l.id),'[]'::jsonb),'nao_lida',EXISTS(SELECT 1 FROM whatsapp_conversas cv WHERE cv.contato_id=l.contato_id AND cv.nao_lidas>0 AND inovachat_pode_ver(cv.company_id,cv.status,cv.responsavel_id,cv.setor_id::text)),'pode_editar',crm__pode_editar(l)) ORDER BY l.etapa_atualizada_em DESC) FROM crm_leads l JOIN whatsapp_contatos ct ON ct.id=l.contato_id WHERE l.company_id=c),'[]'::jsonb),
 'resumo',jsonb_build_object('abertos',(SELECT count(*) FROM crm_leads WHERE company_id=c AND fechado_em IS NULL),'criados_30d',(SELECT count(*) FROM crm_leads WHERE company_id=c AND criado_em>now()-interval '30 days'),'convertidos_30d',(SELECT count(*) FROM crm_leads WHERE company_id=c AND convertido_em>now()-interval '30 days'),'retornos_hoje',(SELECT count(*) FROM crm_leads WHERE company_id=c AND fechado_em IS NULL AND proximo_contato_em<(((now() AT TIME ZONE 'America/Fortaleza')::date+1)::timestamp AT TIME ZONE 'America/Fortaleza'))),
 'usuarios',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'nome',coalesce(nullif(trim(full_name),''),'Usuário')) ORDER BY full_name) FROM profiles WHERE company_id=c AND coalesce(is_active,true)),'[]'::jsonb));
END $$;
CREATE OR REPLACE FUNCTION public.crm_resultados(p_desde date,p_ate date,p_responsavel uuid DEFAULT NULL,p_origem text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c uuid:=get_user_company_id(auth.uid()); r jsonb;
BEGIN
 IF NOT crm_pode_ver(c) THEN RAISE EXCEPTION 'Sem acesso ao CRM'; END IF;
 IF p_desde IS NULL OR p_ate IS NULL OR p_ate<p_desde OR p_ate-p_desde>3660 THEN RAISE EXCEPTION 'Período inválido'; END IF;
 WITH base AS (SELECT l.*, (l.paciente_id IS NOT NULL AND l.convertido_em<((p_ate+1)::timestamp AT TIME ZONE 'America/Fortaleza')) convertido FROM crm_leads l WHERE l.company_id=c AND l.criado_em>=(p_desde::timestamp AT TIME ZONE 'America/Fortaleza') AND l.criado_em<((p_ate+1)::timestamp AT TIME ZONE 'America/Fortaleza') AND (p_responsavel IS NULL OR l.responsavel_id=p_responsavel) AND (p_origem IS NULL OR l.origem=p_origem)),
 etapas AS (SELECT e.id,e.nome,e.cor,e.ordem,count(DISTINCT b.id)::int quantidade FROM crm_etapas e LEFT JOIN crm_lead_eventos ev ON ev.etapa_id=e.id AND ev.tipo IN ('criado','etapa') AND ev.criado_em<((p_ate+1)::timestamp AT TIME ZONE 'America/Fortaleza') LEFT JOIN base b ON b.id=ev.lead_id WHERE e.company_id=c GROUP BY e.id),
 perdas AS (SELECT m.id,m.nome,count(*)::int quantidade FROM base b JOIN crm_etapas e ON e.id=b.etapa_id AND e.tipo='perdido' JOIN crm_motivos_perda m ON m.id=b.motivo_perda_id WHERE b.fechado_em<((p_ate+1)::timestamp AT TIME ZONE 'America/Fortaleza') GROUP BY m.id),
 origens AS (SELECT origem,count(*)::int criados,count(*) FILTER(WHERE convertido)::int convertidos FROM base GROUP BY origem),
 responsaveis AS (SELECT responsavel_id,coalesce(inovachat_nome_usuario(responsavel_id),'Sem responsável') nome,count(*)::int criados,count(*) FILTER(WHERE convertido)::int convertidos FROM base GROUP BY responsavel_id),
 tempos AS (SELECT b.id,extract(epoch FROM (min(ev.criado_em)-b.criado_em))/86400 dias FROM base b JOIN crm_lead_eventos ev ON ev.lead_id=b.id AND ev.automacao='agendamento_criado' AND ev.tipo IN ('criado','etapa') AND ev.criado_em<((p_ate+1)::timestamp AT TIME ZONE 'America/Fortaleza') GROUP BY b.id,b.criado_em)
 SELECT jsonb_build_object('criados',(SELECT count(*) FROM base),'convertidos',(SELECT count(*) FROM base WHERE convertido),'taxa',coalesce((SELECT round(100.0*count(*) FILTER(WHERE convertido)/nullif(count(*),0),1) FROM base),0),'perdidos',coalesce((SELECT sum(quantidade) FROM perdas),0),'tempo_agendamento',(SELECT round(avg(greatest(dias,0)),2) FROM tempos),'valor_convertidos',coalesce((SELECT sum(valor_estimado) FROM base WHERE convertido),0),'funil',coalesce((SELECT jsonb_agg(to_jsonb(etapas) ORDER BY ordem) FROM etapas),'[]'::jsonb),'perdas',coalesce((SELECT jsonb_agg(to_jsonb(perdas)||jsonb_build_object('percentual',round(100.0*quantidade/nullif((SELECT sum(quantidade) FROM perdas),0),1)) ORDER BY quantidade DESC,nome) FROM perdas),'[]'::jsonb),'origens',coalesce((SELECT jsonb_agg(to_jsonb(origens)||jsonb_build_object('taxa',round(100.0*convertidos/nullif(criados,0),1)) ORDER BY criados DESC) FROM origens),'[]'::jsonb),'responsaveis',coalesce((SELECT jsonb_agg(to_jsonb(responsaveis)||jsonb_build_object('taxa',round(100.0*convertidos/nullif(criados,0),1)) ORDER BY criados DESC) FROM responsaveis),'[]'::jsonb)) INTO r;
 RETURN r;
END $$;
REVOKE ALL ON FUNCTION public.crm_resultados(date,date,uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.crm_resultados(date,date,uuid,text) TO authenticated;